	/** Build a local status-aware companion link without performing an installation or activation.
	 * @return array|null Escaped-at-output URL and translated label, or null without the required capability.
	 */
	public static function scripture_action(): ?array {
		require_once ABSPATH . 'wp-admin/includes/plugin.php';
		$file = '';
		$headers = array();
		foreach ( get_plugins() as $candidate => $plugin ) {
			if ( 'daily-scripture.php' === basename( $candidate ) && 'daily-scripture' === ( $plugin['TextDomain'] ?? '' ) ) {
				$file = $candidate;
				$headers = $plugin;
				break;
			}
		}
		if ( $file && is_plugin_active( $file ) ) {
			return current_user_can( 'manage_options' ) ? array( 'url' => admin_url( 'admin.php?page=daily-scripture' ), 'label' => __( 'Open Daily Scripture', 'tuerchenzeit' ) ) : null;
		}
		if ( $file ) {
			$network_only = is_multisite() && ! empty( $headers['Network'] );
			if ( ! current_user_can( 'activate_plugin', $file ) || ( $network_only && ! current_user_can( 'manage_network_plugins' ) ) ) { return null; }
			$url = $network_only ? network_admin_url( 'plugins.php' ) : admin_url( 'plugins.php' );
			$url = add_query_arg( array( 'action' => 'activate', 'plugin' => $file ), $url );
			return array( 'url' => wp_nonce_url( $url, 'activate-plugin_' . $file ), 'label' => __( 'Activate plugin', 'tuerchenzeit' ) );
		}
		if ( ! current_user_can( 'install_plugins' ) ) { return null; }
		$url = is_multisite() ? network_admin_url( 'plugin-install.php?tab=deckerweb' ) : admin_url( 'plugin-install.php?tab=deckerweb' );
		return array( 'url' => $url, 'label' => __( 'Install plugin now', 'tuerchenzeit' ) );
	}

	/** Render escaped prose with fixed, accessible product-name formatting.
	 * @param string $text Translated plain text.
	 * @return void
	 */
	private static function copy( string $text ): void {
		$text = str_replace( array( 'Daily Scripture', 'daily_scripture_passage' ), array( '<em class="ttz-product-name">Daily Scripture</em>', '<code class="ttz-inline-code">daily_scripture_passage</code>' ), esc_html( $text ) );
		echo wp_kses( $text, array( 'em' => array( 'class' => true ), 'code' => array( 'class' => true ) ) );
	}

