		?><details class="ttz-options"><summary><?php esc_html_e( 'Season, privacy and original content', 'tuerchenzeit' ); ?></summary>
		<?php foreach ( array( 'protect_references' => __( 'Protect linked original content until opening', 'tuerchenzeit' ), 'today_button' => __( 'Show a button for today’s door', 'tuerchenzeit' ), 'remember' => __( 'Offer optional visited-door markers on this browser', 'tuerchenzeit' ), 'shuffle' => __( 'Mix the door numbers in a stable order', 'tuerchenzeit' ), 'closing_enabled' => __( 'Show a greeting from December 25 onward', 'tuerchenzeit' ) ) as $key => $label ) : ?>
