		<p><label><?php esc_html_e( 'Opening animation', 'tuerchenzeit' ); ?> <select name="ttz_settings[animation]"><?php foreach ( array( 'none' => __( 'None', 'tuerchenzeit' ), 'fade' => __( 'Gentle fade', 'tuerchenzeit' ), 'door' => __( 'Small door movement', 'tuerchenzeit' ) ) as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $s['animation'], $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label></p>
		<p><label><?php esc_html_e( 'Christmas closing message (paragraphs, bold and italic)', 'tuerchenzeit' ); ?><textarea class="large-text" rows="3" name="ttz_settings[closing_text]"><?php echo esc_textarea( $s['closing_text'] ); ?></textarea></label></p></details>
