		<?php foreach ( array( 'missing' => __( 'Missing doors:', 'tuerchenzeit' ), 'unavailable' => __( 'Check publication:', 'tuerchenzeit' ) ) as $key => $label ) { if ( $r[ $key ] ) { echo '<p>' . esc_html( $label ) . ' '; foreach ( $r[ $key ] as $day ) { echo '<a class="ttz-door-jump" data-door-jump href="#ttz-door-' . esc_attr( $day ) . '">' . esc_html( sprintf( __( 'Door %d', 'tuerchenzeit' ), $day ) ) . '</a> '; } echo '</p>'; } } ?>
		<p><?php echo esc_html( $r['published'] ? __( 'Calendar published.', 'tuerchenzeit' ) : __( 'Calendar not published yet.', 'tuerchenzeit' ) ); ?> <?php if ( (int) $s['year'] !== (int) wp_date( 'Y' ) ) { esc_html_e( 'The calendar year differs from the current year. Check that this is intentional.', 'tuerchenzeit' ); } ?></p>
		<?php if ( 'auto-draft' !== $post->post_status ) : ?>
		<p class="ttz-date-preview-row"><label><?php esc_html_e( 'Simulated date in the WordPress timezone', 'tuerchenzeit' ); ?><br><input type="datetime-local" data-simulated-date value="<?php echo esc_attr( $s['year'] . '-12-08T12:00' ); ?>"></label> <a class="button" data-date-preview target="_blank" rel="noopener" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=ttz_preview&calendar=' . $post->ID ), 'ttz_preview_page_' . $post->ID ) ); ?>"><?php esc_html_e( 'Open date preview', 'tuerchenzeit' ); ?></a></p><p><?php esc_html_e( 'Preview and readiness use saved settings. Save changes first. The simulated date never changes public opening times.', 'tuerchenzeit' ); ?></p>
		<p><a class="button" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=ttz_export&calendar=' . $post->ID ), 'ttz_export_' . $post->ID ) ); ?>"><?php esc_html_e( 'Export calendar JSON', 'tuerchenzeit' ); ?></a> <a href="<?php echo esc_url( admin_url( 'edit.php?post_type=' . Calendar::TYPE . '&page=ttz-guide' ) ); ?>"><?php esc_html_e( 'Help & inspiration', 'tuerchenzeit' ); ?></a></p>
		<?php endif; $unresolved = (int) get_post_meta( $post->ID, '_ttz_import_unresolved', true ); if ( $unresolved ) { echo '<p>' . esc_html( sprintf( __( 'Import: %d references or images need reassignment. Review all doors before publishing.', 'tuerchenzeit' ), $unresolved ) ) . '</p>'; } ?></section><?php
	}
	/** Render a private standalone simulation using the same frontend and signed AJAX flow. @return void */
	public static function preview(): void {
		$id = absint( $_GET['calendar'] ?? 0 );
		if ( ! current_user_can( 'manage_options' ) || ! current_user_can( 'edit_post', $id ) || ! Calendar::get( $id, true ) ) { wp_die( '', '', array( 'response' => 403 ) ); } check_admin_referer( 'ttz_preview_page_' . $id );
		$date = is_string( $_GET['date'] ?? null ) ? sanitize_text_field( wp_unslash( $_GET['date'] ) ) : '';
		if ( null === Calendar::switch_time( $date ) ) { $date = Calendar::settings( $id )['year'] . '-12-08T12:00'; }
		// admin-post.php has no current screen. Render this standalone preview without the admin toolbar.
		remove_action( 'wp_body_open', 'wp_admin_bar_render', 0 );
		remove_action( 'wp_footer', 'wp_admin_bar_render', 1000 );
		remove_action( 'wp_head', 'wp_admin_bar_header' );
		remove_action( 'wp_head', '_admin_bar_bump_cb' );
		remove_action( 'wp_enqueue_scripts', 'wp_enqueue_admin_bar_bump_styles' );
		wp_dequeue_style( 'admin-bar' ); wp_dequeue_script( 'admin-bar' );
		nocache_headers(); header( 'Cache-Control: no-store, private, max-age=0' ); header( 'X-Robots-Tag: noindex, noarchive', true ); Frontend::assets();
		echo '<!doctype html><html ' . get_language_attributes() . '><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta charset="utf-8"><title>Türchenzeit</title>'; wp_head(); echo '</head><body>'; wp_body_open();
		echo Frontend::shortcode( array( 'id' => $id, 'preview' => '1', 'date' => $date ) ); wp_footer(); echo '</body></html>'; exit;
	}
}
